mapper.select:
select b.id, u1.nick_name, v.name as venue_name, c.name as course_name, u2.nick_name as coach_name, b.status, b.book_time
from book b
LEFT JOIN sys_user u1 ON b.user_id=u1.user_id
LEFT JOIN venue v ON b.venue_id=v.id
LEFT JOIN course c ON b.course_id=c.id
LEFT JOIN sys_user u2 ON b.coach_id=u2.user_id

     and b.user_id = #{userId}
     and b.venue_id = #{venueId}
     and b.course_id = #{courseId}
     and b.coach_id = #{coachId}
     and b.status = #{status}
     and DATE(b.book_time) = #{bookTime}
     and u1.nick_name like concat('%', #{nickName}, '%')
     and v.name like concat('%', #{venueName}, '%')
     and c.name like concat('%', #{courseName}, '%')
     and u2.nick_name like concat('%', #{coachName}, '%')

SELECT COUNT(*)
FROM book
WHERE user_id = #{userId}
AND DATE(book_time) = #{date}

SELECT u.nick_name as name, COUNT(b.id) AS number FROM sys_user_role ur LEFT JOIN sys_user u ON ur.user_id=u.user_id LEFT JOIN book b ON u.user_id=b.coach_id AND b.status NOT IN (0, 2)
AND b.create_time > #{begin}
AND b.create_time < #{end}
and ur.role_id=3
GROUP BY u.user_id ORDER BY number DESC LIMIT 0, 10;

SELECT COUNT(*)
FROM book
WHERE coach_id = #{coachId}
  AND DATE(book_time) = #{date}

mapper.update:
update book
user_id = #{userId}, venue_id = #{venueId}, course_id = #{courseId}, coach_id = #{coachId}, status = #{status}, book_time = #{bookTime}, create_time = #{createTime},
where id = #{id}
